     */
    public function live(Request $request, LiveRoomServices $liveRoom)
    {
		[$limit] = $request->getMore([
            ['limit', 0],
        ], true);
        return app('json')->success($liveRoom->userList([], (int)$limit));
    }

    /**
     * 获取直播回放
     * @param $id
     * @param LiveRoomServices $lvieRoom
     * @return mixed
     */
    public function livePlaybacks($id, LiveRoomServices $lvieRoom)
    {
        return app('json')->success($lvieRoom->getPlaybacks((int)$id));
    }
}

    public function userList(array $where, int $limit = 0)
    {
		if ($limit) {
			$page = 0;
		} else {
			[$page, $limit] = $this->getPageValue();
		}
        $where['is_show'] = 1;
        $where['is_del'] = 0;
        $list = $this->dao->getList($where, '*', ['roomGoods.goods', 'anchor'], $page, $limit);
        foreach ($list as &$item) {
            $item['roomid'] = $item['room_id'];
            $item['goods'] = [];
            $item['show_time'] = date('m/d H:i', strtotime($item['start_time']));
            if (isset($item['roomGoods']) && $item['roomGoods']) {
                $item['goods'] = array_column($item['roomGoods'], 'goods');
            }
            if (in_array($item['live_status'], [105, 106])) {
                $item['live_status'] = 101;
            }
            if (in_array($item['live_status'], [104, 107])) {
                $item['live_status'] = 103;
            }
            unset($item['roomGoods']);
        }
        return $list;
    }

public function getList(array $where, string $field = '*', array $with = [], int $page = 0, int $limit = 0)
{
    return $this->search($where)->field($field)->with($with)
    	->when($page && $limit, function ($query) use ($page, $limit) {
            $query->page($page, $limit);
        })->when(!$page && $limit, function ($query) use ($page, $limit) {
            $query->limit($limit);
        })->order('sort desc,id desc')->select()->toArray();
}

public function roomGoods()
{
    return $this->hasMany(LiveRoomGoods::class, 'live_room_id', 'id');
}

