  if(boundary==='raw'){r.props.modelValue=JSON.stringify([{...r.value()[0],external:true},fresh(20)]);await tick();if(aba)r.props.modelValue=raw;}
  if(boundary==='editor'){r.props.editorKey='live:other';await tick();if(aba)r.props.editorKey='live:2';}
  if(boundary==='page'){r.props.pageId=9;await tick();if(aba)r.props.pageId=2;}
  if(boundary==='published'){r.props.pagePublished=true;await tick();if(aba)r.props.pagePublished=false;}
  if(boundary==='actor'){r.storage.set('admin_token','B');r.actor.token='B';r.window.dispatchEvent(new Event('admin-session-changed'));await tick();if(aba){r.storage.set('admin_token','A');r.actor.token='A';r.window.dispatchEvent(new Event('admin-session-changed'));}}
